-- 211_stopword_blocklist_reduced_forms.sql
--
-- qa_stopword a qa_blocklist dostávají tři odvozené sloupce jako qa_synonym,
-- plus tři příznaky, na které z nich se pravidlo uplatní.
--
-- PROČ. Dnes se všechny tři tvary porovnávají proti JEDNOMU sloupci `term`,
-- protože drop() dostává tutéž množinu stopwords_of() ve všech třech větvích
-- (normalize.py:341, lemmatizer.py, stemmer.py). Uložený term je ale povrchový
-- tvar, takže na stem sedne jen náhodou. Změřeno na scope='index', lang='cs':
--   155 termů, z toho 44 se NEROVNÁ vlastnímu stemu
--   behem→beh, kolem→kol, bude→bud, jsou→jso, mezi→meh, nebo→neb, ...
-- Těch 44 slov tedy propadá do stem větve. „během" tam navíc koliduje s „běh".
--
-- DVĚ OSY, ZÁMĚRNĚ ODDĚLENÉ.
--   term_norm/term_lemma/term_stem  = ODVOZENÁ DATA. Plní se VŽDY, nikdy NULL,
--       i tam, kde se tvar nepoužívá. To je právě to, co dovolí filtrovat
--       „ukaž řádky se stejným stemem, ale jiným slovem" — a najít kolize.
--   use_norm/use_lemma/use_stem     = ROZHODNUTÍ, jestli se pravidlo na daný
--       tvar uplatní.
-- Kdyby se „nepoužívat" kódovalo prázdnou hodnotou v odvozeném sloupci, ztratí
-- se přesně ta viditelnost, kvůli které sloupce vznikly: nebezpečné termy jsou
-- ty, které by se vyprázdnily, takže by zmizely z dohledu jako první.
--
-- KONVENCE OBSAHU: čistá redukce po slovech, BEZ aplikace stoplistu, spojená
-- mezerou. Pozor, qa_synonym má jinou — tam se u frází stoplist aplikoval
-- („škola v přírodě" → „skola priroda", „v" chybí). Sjednotit až s přepočtem.
--
-- FORM SE RUŠÍ. Sloupec `form` z migrace 209 uměl jen jednu hodnotu nebo 'all',
-- takže nešlo říct „na norm a lemma ano, na stem ne" — a to je ten častý případ.
-- Navíc byl v PK, takže „norm i lemma" znamenalo dva řádky. Nikdo ho nečte
-- (ověřeno) a všech 680 řádků má 'all', takže se ruší beze ztráty.
--
-- MIGRACE JE ZATÍM NEČINNÁ. settings.py:89 čte pořád jen `term`. Aby příznaky
-- něco dělaly, musí se změnit i kód — a tam se teprve rozhodne, co znamená
-- use_stem: dnes se v stem větvi zastaví 111 ze 155 termů (ty, jejichž stem se
-- náhodou rovná termu). Zapnutí term_stem by přidalo zbylých 44, vypnutí by
-- ubralo těch 111. Ani jedno není „současné chování".

-- POZOR NA cfg. Hodnoty níž jsou spočítané reálným kódem ze search kontejneru
-- s `cfg` sestaveným z settings.config.engines — jako to dělá ChunkLemmatizer
-- (_load_ctx v EDU_AI_QA.json). S cfg=None se de a es nezastemují vůbec
-- (engine_name vrátí prázdno) a 66 z 680 řádků má chybný term_stem: eine→eine
-- místo eine→ein. Stoplist se naopak NEaplikuje: na stopslovo by ho aplikovat
-- znamenalo dostat prázdno.
--

BEGIN;

ALTER TABLE edu_ai.qa_stopword
  ADD COLUMN IF NOT EXISTS term_norm  text    NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS term_lemma text    NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS term_stem  text    NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS use_norm   boolean NOT NULL DEFAULT true,
  ADD COLUMN IF NOT EXISTS use_lemma  boolean NOT NULL DEFAULT true,
  ADD COLUMN IF NOT EXISTS use_stem   boolean NOT NULL DEFAULT false;

ALTER TABLE edu_ai.qa_blocklist
  ADD COLUMN IF NOT EXISTS term_stem  text    NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS use_norm   boolean NOT NULL DEFAULT true,
  ADD COLUMN IF NOT EXISTS use_lemma  boolean NOT NULL DEFAULT true,
  ADD COLUMN IF NOT EXISTS use_stem   boolean NOT NULL DEFAULT false;

