-- qa_blocklist má 42 řádků s term_lemma IS NULL a route.py:138 čte NULL jako
-- „přeskoč". Doplnit je by tiše rozšířilo blokování, proto se lemma NEDOPLŇUJE
-- a místo toho se na těch řádcích shodí příznak — stejný účinek, ale viditelný.
UPDATE edu_ai.qa_blocklist SET use_lemma = false WHERE term_lemma IS NULL;

-- form byl v PK, takže se PK musí přestavět dřív, než sloupec zmizí.
--
-- PODMÍNĚNĚ: migrace 209, která `form` zavedla, neproběhla všude. Produkce ji
-- nemá (ověřeno na dumpu 5. 9. 2026: qa_stopword má term, lang, is_active, note,
-- created_at, scope a PK už je (lang, term, scope)). Nepodmíněný DROP COLUMN by
-- tam spadl a odrolloval by CELOU tuhle migraci včetně naplněných sloupců.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.columns
             WHERE table_schema = 'edu_ai' AND table_name = 'qa_stopword'
               AND column_name = 'form') THEN
    ALTER TABLE edu_ai.qa_stopword DROP CONSTRAINT qa_stopword_pkey;
    ALTER TABLE edu_ai.qa_stopword ADD PRIMARY KEY (lang, term, scope);
    ALTER TABLE edu_ai.qa_stopword DROP COLUMN form;
  END IF;
END $$;

CREATE INDEX IF NOT EXISTS qa_stopword_term_stem_idx  ON edu_ai.qa_stopword  (lang, term_stem);
CREATE INDEX IF NOT EXISTS qa_stopword_term_lemma_idx ON edu_ai.qa_stopword  (lang, term_lemma);
CREATE INDEX IF NOT EXISTS qa_blocklist_term_stem_idx ON edu_ai.qa_blocklist (lang, term_stem);

COMMIT;
